const staticData = $getWorkflowStaticData('global');
const lastCheckedAt = staticData.last_checked_at ||
  new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();
staticData.last_checked_at = new Date().toISOString();
return [{ json: { last_checked_at: lastCheckedAt } }];

const jobs = $json.body.jobs || [];
const run = $('각 실패 run 분리').first().json;
const branch = run.head_branch;
const runId = run.id;
const runName = run.name;
const commitSha = run.head_sha;

// 실패한 job의 steps에서 실패 유형 분류
let failureType = 'build_failed';
let fixable = false;
let logExcerpt = '';
let githubJobId = null;

for (const job of jobs) {
  if (job.conclusion !== 'failure') continue;
  githubJobId = job.id;
  for (const step of (job.steps || [])) {
    if (step.conclusion !== 'failure') continue;
    const stepName = (step.name || '').toLowerCase();
    if (stepName.includes('format check (whitespace)') || stepName.includes('charset')) {
      failureType = 'format_failed'; fixable = true;
    } else if (stepName.includes('format check (style)')) {
      failureType = 'style_failed'; fixable = true;
    } else if (stepName.includes('test')) {
      failureType = 'test_failed';
    } else if (stepName.includes('gate-check') || stepName.includes('sdlc gate')) {
      failureType = 'gate_failed';
    }
    logExcerpt = `Step: ${step.name} / Job: ${job.name}`;
    break;
  }
  if (logExcerpt) break;
}

return [{
  json: {
    failure_type: failureType,
    source: 'github_actions',
    message: `CI 실패: ${runName} / branch: ${branch} / run_id: ${runId}`,
    log_excerpt: logExcerpt,
    fixable_by_ai: fixable,
    metadata: JSON.stringify({ branch, run_id: runId, run_name: runName }),
    branch,
    git_hub_run_id: runId,
    git_hub_job_id: githubJobId,
    commit_sha: commitSha,
    workflow_name: runName
  }
}];
